 * for when a "whole view" already exists to hang the explanation off of.
 */
@Composable
fun DataCardTitleWithInfo(title: String, onInfoClick: () -> Unit) {
    val pulseColors = LocalPulseColors.current

    Row(verticalAlignment = Alignment.CenterVertically) {
        DataCardTitleLabel(title = title)
        Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_tiny)))
        Icon(
            painter = painterResource(id = R.drawable.ic_info),
            contentDescription = stringResource(id = R.string.stock_detail_view_definitions_content_description, title),
